@contextmanager
def army_timing_stage(stage: str, *, step: str, enabled: bool = True,
                      native_request_id: str | None = None):
    """Optional scalar-only timing; no gameplay reads or changed exception flow."""
    timer = start_army_timing(stage, native_request_id=native_request_id) if enabled else None
    try:
        yield
    finally:
        finish_army_timing(timer, step=step)
